       $$('.doc-status',docsPanel).forEach(select=>{const saved=(app.documents||[]).find(doc=>doc.id===select.dataset.document)?.status;select.add(new Option('Superseded · replaced/obsolete','Superseded'));select.value=saved||select.value;});
