function ageOn(dob,at=new Date()){if(!dob)return null;const birth=new Date(`${dob}T12:00:00`);if(Number.isNaN(birth.getTime()))return null;let age=at.getFullYear()-birth.getFullYear();if(at.getMonth()<birth.getMonth()||(at.getMonth()===birth.getMonth()&&at.getDate()<birth.getDate()))age--;return age;}
function buildPolicyPanel(app){
  const d=app.data||{},k=d.kyc||{},f=d.facility||{},g=d.guarantor||{},c=d.cic||{};
  const months=f.tenure_months===''||f.tenure_months==null?null:Number(f.tenure_months);const maturity=new Date();if(months!==null&&Number.isFinite(months))maturity.setMonth(maturity.getMonth()+months);
  const borrowerAge=ageOn(k.dob),borrowerMaturity=months===null?null:ageOn(k.dob,maturity),guarantorRows=[{dob:g.dob,name:g.name},...(Array.isArray(g.additional_guarantors)?g.additional_guarantors:[])];
  const guarantorAges=guarantorRows.filter(row=>row.name||row.dob).map(row=>ageOn(row.dob));
  const guarantorMaturityAges=months===null?[]:guarantorRows.filter(row=>row.name||row.dob).map(row=>ageOn(row.dob,maturity));
  const vehicleYears=[f.year,...(Array.isArray(f.vehicles)?f.vehicles.map(vehicle=>vehicle.year):[])].filter(value=>value!==''&&value!=null).map(Number);
  const vehicleAgeState=vehicleYears.length?vehicleYears.every(year=>new Date().getFullYear()-year<7):null;
  const quotationTotal=Number(f.quotation||0)+(Array.isArray(f.vehicles)?f.vehicles.reduce((sum,vehicle)=>sum+Number(vehicle.quotation||0),0):0);
  const checks=[
    ['Borrower age is at least 21',borrowerAge===null?null:borrowerAge>=21],
    ['Borrower age at maturity is 70 or below',borrowerMaturity===null?null:borrowerMaturity<=70],
    ['Vehicle age is below 7 years',vehicleAgeState],
    ['Loan tenure is below 6 years',months===null?null:months<72],
    ['Tenure is less than vehicle age',null],
    ['Guarantor is available',guarantorRows.some(row=>row.name)?true:null],
    ['All guarantors are at least 18',!guarantorAges.length||guarantorAges.some(age=>age===null)?null:guarantorAges.every(age=>age>=18)],
    ['All guarantors at maturity are 70 or below',!guarantorMaturityAges.length||guarantorMaturityAges.some(age=>age===null)?null:guarantorMaturityAges.every(age=>age<=70)],
    ['Loan is within 60% of total quotation',!quotationTotal||!Number(f.amount)?null:Number(f.amount)<=quotationTotal*.6],
    ['Borrower is not a PEP',!k.pep||k.pep==='Pending'?null:k.pep==='No'],
    ['Driving license is not expired',!k.license_expiry?null:new Date(`${k.license_expiry}T23:59:59`)>=new Date()],
    ['Customer has at least 2 years of experience',k.experience_years==null||k.experience_years===''?null:Number(k.experience_years)>=2],
    ['No other loan facilities with this bank',!k.other_bank_loans||k.other_bank_loans==='Pending'?null:k.other_bank_loans==='None'],
    ['CIC probability of default is below 10%',c.probability_default==null||c.probability_default===''?null:Number(c.probability_default)<10],
    ['No active CIC overdue',!c.active_overdue||c.active_overdue==='Pending'?null:c.active_overdue==='No'],
    ['No overdue in last six installments',!c.last_six_overdue||c.last_six_overdue==='Pending'?null:c.last_six_overdue==='No'],
    ['No active blacklisting',!c.blacklist_active||c.blacklist_active==='Pending'?null:c.blacklist_active==='None'],
    ['No blacklisting history',!c.blacklist_history||c.blacklist_history==='Pending'?null:c.blacklist_history==='None'],
    ['All active accounts are pass category',!c.account_category?null:/^pass$/i.test(c.account_category)],
    ['All guaranteed accounts are pass category',!c.guaranteed_category?null:/^pass$/i.test(c.guaranteed_category)]
  ];
  const result=checks.map(([label,state])=>`<div class="policy-row ${state===true?'policy-pass':state===false?'policy-fail':'policy-pending'}"><span>${state===true?'✓':state===false?'!':'•'}</span><b>${esc(label)}</b><small>${state===true?'Pass':state===false?'Exception':'Pending'}</small></div>`).join('');
  return `<div class="panel"><div class="panel-head"><div><h2>Policy & CIC acceptance checks</h2><p>Indicators are derived from entered data. Exceptions require a documented human decision.</p></div><span class="stage">${checks.filter(([,x])=>x===true).length} / ${checks.length} pass</span></div><div class="policy-grid">${result}</div><p class="notice">The brief's “tenure less than age of vehicle” rule is undefined in units/formula. It stays pending for policy-owner confirmation.</p></div>`;
}
async function saveCurrentApplication(){const data=collectFields($('#viewRoot'));if(!Object.keys(data).length){toast('No editable fields are available.');return;}try{await request(`/api/applications/${encodeURIComponent(current.id)}`,{method:'PATCH',body:{version:current.version,data}});toast('Application changes saved.');await openApplication(current.id);}catch(error){showError(error);}}
async function forwardCurrentApplication(){try{let decision={};if(current.stage==='Approval'){decision=collectFields($('#viewRoot')).decision||{};if(!decision.recommendation||!decision.rationale?.trim()){toast('Select a recommendation and enter a rationale.');return;}if(decision.recommendation!=='Recommend decline'&&(!decision.approved_amount||!decision.approved_tenure_months||decision.approved_rate==='')){toast('Enter the approved amount, tenure and interest rate before sending to CAD.');return;}if(decision.recommendation==='Return for clarification'){showReturnModal();return;}}
  const saved=collectFields($('#viewRoot'));
  if(Object.keys(saved).length){await request(`/api/applications/${encodeURIComponent(current.id)}`,{method:'PATCH',body:{version:current.version,data:saved}});current.version++;}
  await request(`/api/applications/${encodeURIComponent(current.id)}/transition`,{method:'POST',body:{action:'forward',remarks:$('#handoffNote')?.value||'',decision,version:current.version}});toast('Application forwarded to the next workflow stage.');await openApplication(current.id);
 }catch(error){showError(error);}}
function showReturnModal(){$('#returnRemarks').value='';$('#returnModal').classList.remove('hidden');$('#returnRemarks').focus();}
async function confirmReturn(event){event.preventDefault();const remarks=$('#returnRemarks').value.trim();if(remarks.length<5){$('#returnRemarks').setCustomValidity('Please provide specific return remarks.');$('#returnRemarks').reportValidity();return;}$('#returnRemarks').setCustomValidity('');try{await request(`/api/applications/${encodeURIComponent(current.id)}/transition`,{method:'POST',body:{action:'return',remarks,version:current.version}});$('#returnModal').classList.add('hidden');toast('Application returned with remarks.');await openApplication(current.id);}catch(error){showError(error);}}
async function uploadDocument(event){const file=event.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);try{const result=await request(`/api/applications/${encodeURIComponent(current.id)}/documents?type=${encodeURIComponent($('#documentType').value)}`,{method:'POST',body:form});toast(result.report_id?'Document uploaded; CAD checks refreshed.':'Document uploaded; readable text extraction is '+(result.extraction_status||'pending')+'.');await openApplication(current.id);}catch(error){showError(error);}finally{event.target.value='';}}
async function renderReports(){
  setPageTitle('Reporting');if(!can('Reporting','R','Portfolio reports'))return showError(new Error('Portfolio reporting is not assigned to your role.'));
  $('#viewRoot').innerHTML=`<div class="page-heading"><div><div class="eyebrow">PORTFOLIO VISIBILITY</div><h1>Entire reporting</h1><p>Filter applications by branch, stage, and submission date. Results are limited by your server-enforced scope.</p></div></div><div class="panel"><div class="filter-bar"><label>Branch<select id="reportBranch"><option value="">All visible branches</option></select></label><label>Stage<select id="reportStage"><option value="">All stages</option>${stages.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Submitted from<input id="reportFrom" type="date"></label><label>Submitted to<input id="reportTo" type="date"></label><button class="btn btn-light" id="runReport">Apply filters</button><button class="btn btn-light hidden" id="exportReport">Export CSV</button></div><div id="reportSummary" class="metrics"></div><div id="reportTable"></div></div><div class="panel"><h2>Stage distribution</h2><div id="stageBreakdown"></div></div>`;
  try{const result=await request('/api/reports');$('#reportBranch').innerHTML='<option value="">All visible branches</option>'+result.branches.map(b=>`<option>${esc(b)}</option>`).join('');if(result.allow_export)$('#exportReport').classList.remove('hidden');renderReportResults(result);$('#runReport').addEventListener('click',runReportFilters);$('#exportReport').addEventListener('click',exportReport);}catch(error){showError(error);}
}
function renderReportResults(result){reportRows=result.applications;const s=result.summary;$('#reportSummary').innerHTML=metric('Applications',s.count,'Filtered records')+metric('Requested exposure',money(s.requested_exposure),'Filtered total')+metric('Branches',result.branches.length,'In report scope')+metric('Stages represented',Object.keys(s.by_stage).length,'Current stages');$('#reportTable').innerHTML=appRows(reportRows);bindOpenButtons($('#reportTable'));$('#stageBreakdown').innerHTML=Object.entries(s.by_stage).map(([stage,count])=>`<div class="document-row"><span>${esc(stage)}</span><b>${count}</b></div>`).join('')||'<div class="empty-state">No records match these filters.</div>';}
async function reportParams(exporting=false){const p=new URLSearchParams();for(const [id,key] of [['reportBranch','branch'],['reportStage','stage'],['reportFrom','from'],['reportTo','to']])if($(`#${id}`).value)p.set(key,$(`#${id}`).value);if(exporting)p.set('export','1');return p;}
async function runReportFilters(){try{const result=await request('/api/reports?'+await reportParams());renderReportResults(result);}catch(error){showError(error);}}
async function exportReport(){try{const result=await request('/api/reports?'+await reportParams(true));const columns=['Application','Customer','Branch','Stage','Status','Amount NPR','Created'];const csv=[columns,...result.applications.map(a=>[a.id,a.customer_name,a.branch,a.stage,a.status,a.amount,a.created_at])].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='credit-review-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500);toast('Report exported.');}catch(error){showError(error);}}
async function renderAdmin(){
  setPageTitle('Access control');if(session.role!=='Superadmin')return showError(new Error('Superadmin access is required.'));
  try{adminData=await request('/api/admin/access');selectedRole='Superadmin';
    $('#viewRoot').innerHTML=`<div class="page-heading"><div><div class="eyebrow">SYSTEM ADMINISTRATION</div><h1>Roles, access & users</h1><p>Manage assignments and module/field CRUD. Superadmin has full access across the matrix.</p></div></div><div class="admin-grid"><section class="panel"><div class="panel-head"><div><h2>User role assignment</h2><p>Role and branch scope are checked server-side.</p></div></div><div class="table-wrap"><table><thead><tr><th>USER</th><th>BRANCH</th><th>ROLE</th><th>SCOPE</th></tr></thead><tbody>${adminData.users.map(u=>`<tr><td><b>${esc(u.display_name)}</b><small class="subtext">${esc(u.username)} · ${esc(u.email)}</small></td><td><input class="assignment-branch" data-id="${u.id}" value="${esc(u.branch)}" ${u.role==='Superadmin'?'disabled':''}></td><td><select class="assignment-role" data-id="${u.id}" ${u.role==='Superadmin'?'disabled':''}>${adminData.roles.map(r=>`<option ${r.name===u.role?'selected':''}>${esc(r.name)}</option>`).join('')}</select></td><td><input class="assignment-scope" data-id="${u.id}" value="${esc(u.scope.join(', '))}" ${u.role==='Superadmin'?'disabled':''}></td></tr>`).join('')}</tbody></table></div><div class="app-actions"><span class="muted">Use All for system-wide branch scope.</span><button class="btn btn-primary" id="saveAssignments">Save assignments</button></div><div class="panel-head" style="margin-top:20px"><div><h2>Add user</h2><p>Initial password must contain at least 12 characters.</p></div></div><form id="addUserForm" class="admin-form"><input name="username" placeholder="Username" required minlength="3"><input name="display_name" placeholder="Full name" required><input name="email" type="email" placeholder="Work email" required><input name="password" type="password" placeholder="Initial password (12+ characters)" required minlength="12"><input name="branch" placeholder="Branch / team" required><input name="scope" placeholder="Scope branches, comma-separated" required><select name="role">${adminData.roles.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select><button class="btn btn-light">＋ Create user</button></form></section><section class="panel"><div class="panel-head"><div><h2>Permission matrix</h2><p>Set CRUD at module and field level.</p></div><select id="adminRoleSelect">${adminData.roles.map(r=>`<option ${r.name===selectedRole?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="perm-chips"><span>C Create</span><span>R Read</span><span>U Update</span><span>D Delete</span></div><div id="permissionMatrix"></div><div class="app-actions"><button class="btn btn-light" id="createCustomRole">＋ Create custom role</button><div class="app-actions-right"><button class="btn btn-danger hidden" id="deleteCustomRole">Delete role</button><button class="btn btn-primary" id="savePermissions">Save permissions</button></div></div></section><section class="panel"><div class="panel-head"><div><h2>Administration audit</h2><p>Role, permission, and assignment changes.</p></div></div><div id="adminAudit"></div></section></div>`;
    drawPermissionMatrix();$('#adminRoleSelect').addEventListener('change',()=>{selectedRole=$('#adminRoleSelect').value;drawPermissionMatrix();});$('#savePermissions').addEventListener('click',savePermissions);$('#createCustomRole').addEventListener('click',createCustomRole);$('#deleteCustomRole').addEventListener('click',deleteCustomRole);$('#saveAssignments').addEventListener('click',saveAssignments);$('#addUserForm').addEventListener('submit',createUser);
    const log=await request('/api/admin/audit');$('#adminAudit').innerHTML=log.events.length?log.events.map(e=>`<div class="audit-item"><b>${esc(e.action)}</b> · ${esc(e.target)}<small class="subtext">${esc(e.display_name)} · ${new Date(e.created_at).toLocaleString()} · ${esc(e.details)}</small></div>`).join(''):'<div class="empty-state">No administration changes recorded.</div>';
  }catch(error){showError(error);}
}
function drawPermissionMatrix(){const role=adminData.roles.find(r=>r.name===selectedRole);if(!role)return;const fixed=selectedRole==='Superadmin';$('#deleteCustomRole').classList.toggle('hidden',!!role.built_in);$('#savePermissions').disabled=fixed;$('#permissionMatrix').innerHTML=Object.entries(adminData.modules).map(([module,fields])=>{const rights=role.permissions[module]||{};const toggles=(field,ops)=>['C','R','U','D'].map(op=>`<label class="perm"><input type="checkbox" data-module="${esc(module)}" data-field="${esc(field)}" data-op="${op}" ${ops?.[op]?'checked':''} ${fixed?'disabled':''}>${op}</label>`).join('');return `<details class="permission-module"><summary><span>${esc(module)}</span><div class="perm-chips">${toggles('__module',rights.__module)}</div></summary>${fields.map(field=>`<div class="field-right"><span>${esc(field)}</span><div>${toggles(field,rights[field])}</div></div>`).join('')}</details>`;}).join('');}
async function savePermissions(){const permissions={};$$('#permissionMatrix input').forEach(input=>{const {module,field,op}=input.dataset;permissions[module]??={};permissions[module][field]??={C:false,R:false,U:false,D:false};permissions[module][field][op]=input.checked;});try{await request(`/api/admin/roles/${encodeURIComponent(selectedRole)}/permissions`,{method:'PUT',body:{permissions}});toast('Module and field permissions saved.');await renderAdmin();selectedRole=$('#adminRoleSelect').value;drawPermissionMatrix();}catch(error){showError(error);}}
async function createCustomRole(){const name=prompt('Name the custom role');if(!name?.trim())return;try{await request('/api/admin/roles',{method:'POST',body:{name:name.trim()}});toast('Custom role created. Configure its permissions.');await renderAdmin();selectedRole=name.trim();$('#adminRoleSelect').value=selectedRole;drawPermissionMatrix();}catch(error){showError(error);}}
async function deleteCustomRole(){if(!confirm(`Delete custom role “${selectedRole}”?`))return;try{await request(`/api/admin/roles/${encodeURIComponent(selectedRole)}`,{method:'DELETE'});toast('Custom role deleted.');await renderAdmin();}catch(error){showError(error);}}
async function saveAssignments(){try{for(const input of $$('.assignment-role')){const id=input.dataset.id;const branch=$(`.assignment-branch[data-id="${id}"]`).value;const scope=$(`.assignment-scope[data-id="${id}"]`).value.split(',').map(x=>x.trim()).filter(Boolean);await request(`/api/admin/users/${id}`,{method:'PATCH',body:{role:input.value,branch,scope}});}toast('User roles and scopes saved.');await renderAdmin();}catch(error){showError(error);}}
async function createUser(event){event.preventDefault();const form=new FormData(event.currentTarget);const payload=Object.fromEntries(form.entries());payload.scope=payload.scope.split(',').map(x=>x.trim()).filter(Boolean);try{await request('/api/admin/users',{method:'POST',body:payload});toast('User account created and assigned.');await renderAdmin();}catch(error){showError(error);}}
function showError(error){toast(error.message||'Something went wrong.');}
$('#loginForm').addEventListener('submit',login);$('#demoRoleSelect').addEventListener('change',()=>{if($('#demoRoleSelect').value)$('#loginUsername').value=$('#demoRoleSelect').value;$('#loginPassword').focus();});$('#returnForm').addEventListener('submit',confirmReturn);$('#returnClose').addEventListener('click',()=>$('#returnModal').classList.add('hidden'));$('#returnCancel').addEventListener('click',()=>$('#returnModal').classList.add('hidden'));$('#returnModal').addEventListener('click',event=>{if(event.target.id==='returnModal')$('#returnModal').classList.add('hidden');});
$('#logoutButton').addEventListener('click',async()=>{try{await request('/api/logout',{method:'POST',body:{}});}catch{}session=null;$('#loginPassword').value='';showLogin();});
